import { test, expect } from '@playwright/test';

test.describe('Login Form Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should focus on the username input when tabbed to', async ({ page }) => {
    await page.keyboard.press('Tab');
    const usernameInput = page.getByLabel('Username');
    await expect(usernameInput).toBeFocused();
  });

  test('should focus on the password input when tabbed to after username', async ({ page }) => {
    await page.keyboard.press('Tab'); // Focus on username
    await page.keyboard.press('Tab'); // Focus on password
    const passwordInput = page.getByLabel('Password');
    await expect(passwordInput).toBeFocused();
  });
});
